// Signs local release builds (`./gradlew assembleRelease` / `bundleRelease`)
// with the Billleaf upload key instead of the debug key. android/ is
// generated by `expo prebuild`, so the change lives here, not in
// build.gradle.
//
// The key and its passwords never enter the repo: Gradle reads them from
// properties, normally in ~/.gradle/gradle.properties (or -P / ORG_GRADLE_PROJECT_*):
//   BILLLEAF_UPLOAD_STORE_FILE      absolute path to the .jks
//   BILLLEAF_UPLOAD_KEY_ALIAS
//   BILLLEAF_UPLOAD_STORE_PASSWORD
//   BILLLEAF_UPLOAD_KEY_PASSWORD
// Without them a release build falls back to the debug key, as before.
// EAS Build doesn't use this: it signs with the credentials EAS holds.
const { withAppBuildGradle } = require("expo/config-plugins")

const MARK = "// billleaf-release-signing"

const SIGNING_CONFIG = `
        release { ${MARK}
            if (project.hasProperty('BILLLEAF_UPLOAD_STORE_FILE')) {
                storeFile file(BILLLEAF_UPLOAD_STORE_FILE)
                storePassword BILLLEAF_UPLOAD_STORE_PASSWORD
                keyAlias BILLLEAF_UPLOAD_KEY_ALIAS
                keyPassword BILLLEAF_UPLOAD_KEY_PASSWORD
            }
        }`

/** @param {string} gradle */
function applySigning(gradle) {
  if (gradle.includes(MARK)) return gradle
  const withConfig = gradle.replace(
    /(signingConfigs\s*\{\s*\n\s*debug\s*\{[^}]*\})/,
    `$1${SIGNING_CONFIG}`
  )
  const withRelease = withConfig.replace(
    /(release\s*\{[^{}]*?)signingConfig signingConfigs\.debug/,
    "$1signingConfig project.hasProperty('BILLLEAF_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug"
  )
  if (withConfig === gradle || withRelease === withConfig) {
    throw new Error(
      "with-release-signing: app/build.gradle no longer matches; update the plugin"
    )
  }
  return withRelease
}

/** @type {import("expo/config-plugins").ConfigPlugin} */
const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (c) => {
    c.modResults.contents = applySigning(c.modResults.contents)
    return c
  })

module.exports = withReleaseSigning
module.exports.applySigning = applySigning
